sp_widget.client_script:
api.controller = function($scope, $location) {

    var c = this;

    /* =====================================================
       NEXORA ROLE
       ===================================================== */

    c.role = c.data.role || 'User';

    c.roleLabel = c.data.roleLabel || c.role;


    /* =====================================================
       ACTION PANEL
       ===================================================== */

    c.actionPanelOpen = false;
    c.actionPanelType = '';
    c.actionPanelTitle = '';


    /* =====================================================
       OPEN ACTION PANEL
       ===================================================== */

    c.openActionPanel = function(type, title, event) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.actionPanelType = type || 'default';
        c.actionPanelTitle = title || 'NEXORA';
        c.actionPanelOpen = true;
    };


    /* =====================================================
       CLOSE ACTION PANEL
       ===================================================== */

    c.closeActionPanel = function(event) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.actionPanelOpen = false;
        c.actionPanelType = '';
        c.actionPanelTitle = '';
    };


    /* =====================================================
       NAVIGATION
       ===================================================== */

    c.goToPage = function(page, event) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.actionPanelOpen = false;

        if (!page) {
            return;
        }

        $location.path('/' + page);
    };


    /* =====================================================
       ROLE HELPERS
       ===================================================== */

    c.isStudent = function() {
        return c.role === 'Student';
    };


    c.isPlacementOfficer = function() {
        return c.role === 'Placement Officer';
    };


    c.isPlacementAdmin = function() {
        return c.role === 'Placement Admin';
    };


    c.isInterviewer = function() {
        return c.role === 'Interviewer';
    };


    c.isStaff = function() {

        return (
            c.role === 'Placement Officer' ||
            c.role === 'Placement Admin'
        );
    };


    /* =====================================================
       DASHBOARD TYPE HELPERS
       ===================================================== */

    c.isStudentDashboard = function() {
        return c.isStudent();
    };


    c.isStaffDashboard = function() {
        return c.isStaff();
    };


    c.isInterviewerDashboard = function() {
        return c.isInterviewer();
    };


    /* =====================================================
       DIRECT PAGE HELPERS
       ===================================================== */

    c.goDashboard = function(event) {
        c.goToPage('dashboard', event);
    };


    c.goStudents = function(event) {
        c.goToPage('students', event);
    };


    c.goCompanies = function(event) {
        c.goToPage('companies', event);
    };


    c.goPlacementDrives = function(event) {
        c.goToPage('placement_drives', event);
    };


    c.goApplications = function(event) {
        c.goToPage('applications', event);
    };


    c.goInterviews = function(event) {
        c.goToPage('interviews', event);
    };


    c.goInterviewManagement = function(event) {
        c.goToPage('interview_management', event);
    };


    c.goInterviewEvaluation = function(event) {
        c.goToPage('interview_evaluation', event);
    };


    c.goMyApplications = function(event) {
        c.goToPage('my_applications', event);
    };


    c.goStudentInterviews = function(event) {
        c.goToPage('stu_interviews', event);
    };


    c.goOfferLetter = function(event) {
        c.goToPage('offer_letter', event);
    };


    c.goDocuments = function(event) {
        c.goToPage('my_documents', event);
    };


    /* =====================================================
       STUDENT DRIVE
       ===================================================== */

    c.openDrive = function(driveId, event) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        if (!driveId) {
            return;
        }

        /*
         * Keep drive navigation inside the existing
         * Nexora Placement Drives page.
         *
         * The selected drive ID is stored in the URL so
         * the Placement Drives widget can read it if needed.
         */

        c.actionPanelOpen = false;

        $location.path('/placement_drives');
    };


    /* =====================================================
       ESCAPE KEY
       ===================================================== */

    var keyHandler = function(event) {

        if (
            event.key === 'Escape' ||
            event.keyCode === 27
        ) {

            if (c.actionPanelOpen) {

                $scope.$applyAsync(function() {
                    c.closeActionPanel();
                });

            }

        }

    };


    /* =====================================================
       KEYBOARD EVENT
       ===================================================== */

    angular.element(document).on(
        'keydown',
        keyHandler
    );


    /* =====================================================
       CLOSE ACTION PANEL ON ROUTE CHANGE
       ===================================================== */

    var locationChangeHandler = $scope.$on(
        '$locationChangeStart',
        function() {

            c.actionPanelOpen = false;
            c.actionPanelType = '';
            c.actionPanelTitle = '';

        }
    );


    /* =====================================================
       CLEANUP
       ===================================================== */

    $scope.$on('$destroy', function() {

        angular.element(document).off(
            'keydown',
            keyHandler
        );

        if (locationChangeHandler) {
            locationChangeHandler();
        }

    });

};

sp_widget.css:
/* =========================================================
   NEXORA ROLE BASED DASHBOARD
   COMPLETE RESPONSIVE CSS
   NAVY + CORAL DESIGN
   ========================================================= */


/* =========================================================
   GLOBAL
   ========================================================= */

*,
*::before,
*::after {
    box-sizing: border-box;
}

.nexora-main {
    width: 85vw;
    min-height: 100vh;

    padding: 50px;

    background: #ffffff;

    color: #172b3f;

    font-family:
        "Inter",
        "Segoe UI",
        Arial,
        sans-serif;

    overflow-x: hidden;
}


.nx-dashboard {
    width: 100%;
    max-width: 1450px;

    margin: 0 auto;

    padding: 24px 26px 45px;
}


/* =========================================================
   WELCOME
   ========================================================= */

.nx-welcome {
    min-height: 218px;

    position: relative;

    margin-bottom: 20px;
    padding: 34px 36px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 25px;

    overflow: hidden;

    border-radius: 17px;

    background:
        linear-gradient(
            115deg,
            #17334b 0%,
            #1b3b55 58%,
            #20435d 100%
        );

    color: #ffffff;

    box-shadow:
        0 9px 28px rgba(25,45,66,0.12);
}


.nx-welcome-decoration {
    position: absolute;

    width: 260px;
    height: 260px;

    right: -70px;
    top: -85px;

    border-radius: 50%;

    border: 1px solid rgba(255,255,255,0.08);

    pointer-events: none;
}


.nx-welcome-decoration::after {
    content: "";

    position: absolute;

    width: 175px;
    height: 175px;

    right: 35px;
    top: 35px;

    border-radius: 50%;

    border: 1px solid rgba(255,255,255,0.06);
}


.nx-welcome-content {
    position: relative;

    z-index: 2;

    min-width: 0;
    max-width: 800px;
}


.nx-eyebrow {
    display: block;

    margin-bottom: 10px;

    color: #ff6b5b;

    font-size: 11px;

    font-weight: 900;

    letter-spacing: 1.5px;
}


.nx-welcome h1 {
    margin: 0;

    color: #ffffff;

    font-size: clamp(27px, 3vw, 39px);

    line-height: 1.15;

    font-weight: 800;

    letter-spacing: -0.8px;

    word-break: break-word;
}


.nx-welcome h1 span {
    color: #ff6b5b;
}


.nx-welcome p {
    max-width: 650px;

    margin: 12px 0 0;

    color: #a9c0d1;

    font-size: 13px;

    line-height: 1.7;
}


/* =========================================================
   PRIMARY BUTTON
   ========================================================= */

.nx-primary-btn {
    position: relative;

    z-index: 3;

    flex-shrink: 0;

    padding: 13px 21px;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 10px;

    border: none;

    border-radius: 9px;

    background: #ff6b5b;

    color: #ffffff;

    font-size: 11px;

    font-weight: 800;

    cursor: pointer;

    white-space: nowrap;

    box-shadow:
        0 8px 20px rgba(255,107,91,0.25);

    transition: all 0.2s ease;
}


.nx-primary-btn:hover {
    background: #ff5e4e;

    transform: translateY(-2px);
}


/* =========================================================
   KPI GRID
   ========================================================= */

.nx-kpi-grid {
    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap: 17px;

    margin-bottom: 20px;
}


.nx-kpi-card {
    min-width: 0;
    min-height: 112px;

    padding: 18px;

    display: flex;

    align-items: center;

    gap: 15px;

    background: #ffffff;

    border: 1px solid #e4e9ef;

    border-radius: 15px;

    box-shadow:
        0 4px 15px rgba(28,49,69,0.045);

    transition: all 0.2s ease;
}


.nx-kpi-card:hover {
    transform: translateY(-3px);

    border-color: #d7dfe7;

    box-shadow:
        0 10px 25px rgba(28,49,69,0.09);
}


.nx-kpi-icon {
    width: 47px;
    height: 47px;

    min-width: 47px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    background: #edf3f7;

    color: #245d83;

    font-size: 18px;
}


.nx-kpi-card:first-child .nx-kpi-icon {
    background: #fff0ed;
    color: #ff6b5b;
}


.nx-kpi-card:nth-child(2) .nx-kpi-icon {
    background: #edf5fa;
    color: #245d83;
}


.nx-kpi-card:nth-child(3) .nx-kpi-icon {
    background: #eef3f6;
    color: #24516c;
}


.nx-kpi-card:nth-child(4) .nx-kpi-icon {
    background: #fff0ed;
    color: #ff6b5b;
}


.nx-kpi-info {
    min-width: 0;
}


.nx-kpi-info strong {
    display: block;

    margin-bottom: 4px;

    color: #172b3f;

    font-size: 25px;

    line-height: 1;

    font-weight: 800;
}


.nx-kpi-info span {
    display: block;

    margin-bottom: 3px;

    color: #65798a;

    font-size: 11px;

    font-weight: 600;
}


.nx-kpi-info small {
    display: block;

    color: #a1adb7;

    font-size: 9px;

    line-height: 1.4;
}


/* =========================================================
   COMMON CARD
   ========================================================= */

.nx-card {
    min-width: 0;

    background: #ffffff;

    border: 1px solid #e4e9ef;

    border-radius: 15px;

    overflow: hidden;

    box-shadow:
        0 4px 15px rgba(28,49,69,0.045);
}


.nx-card-header {
    min-height: 72px;

    padding: 16px 20px;

    display: flex;

    align-items: center;
    justify-content: space-between;

    gap: 15px;

    border-bottom: 1px solid #edf0f3;
}


.nx-card-header > div {
    min-width: 0;
}


.nx-card-eyebrow {
    display: block;

    color: #a1adb7;

    font-size: 9px;

    font-weight: 900;

    letter-spacing: 1.4px;
}


.nx-card-header h2 {
    margin: 5px 0 0;

    color: #19344b;

    font-size: 15px;

    line-height: 1.2;

    font-weight: 800;
}


.nx-view-btn {
    flex-shrink: 0;

    padding: 5px 0;

    border: none;

    background: transparent;

    color: #ff6b5b;

    font-size: 10px;

    font-weight: 800;

    cursor: pointer;

    white-space: nowrap;
}


.nx-view-btn:hover {
    color: #e85344;
}


/* =========================================================
   JOURNEY
   ========================================================= */

.nx-journey-card {
    margin-bottom: 20px;
}


.nx-journey-wrapper {
    min-height: 98px;

    padding: 22px 25px;

    display: flex;

    align-items: center;
}


.nx-journey-step {
    min-width: 72px;

    display: flex;

    align-items: center;

    gap: 9px;
}


.nx-journey-circle {
    width: 43px;
    height: 43px;

    min-width: 43px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #f0f4f7;

    color: #81909d;

    border: 1px solid #e0e7ed;

    font-size: 13px;
}


.nx-journey-circle.active {
    background: #fff0ed;

    color: #ff6b5b;

    border-color: #ffd0c9;
}


.nx-journey-text {
    display: flex;

    flex-direction: column;

    min-width: 0;
}


.nx-journey-text strong {
    color: #19344b;

    font-size: 13px;

    font-weight: 800;
}


.nx-journey-text span {
    margin-top: 3px;

    color: #8998a5;

    font-size: 9px;

    white-space: nowrap;
}


.nx-journey-line {
    flex: 1;

    height: 1px;

    min-width: 25px;

    margin: 0 10px;

    background: #dfe5ea;
}


/* =========================================================
   TWO COLUMN
   ========================================================= */

.nx-content-grid {
    display: grid;

    grid-template-columns:
        minmax(0, 1fr)
        minmax(0, 1fr);

    gap: 18px;

    margin-bottom: 20px;
}


/* =========================================================
   APPLICATION
   ========================================================= */

.nx-application-list {
    width: 100%;
}


.nx-application {
    min-width: 0;
    min-height: 66px;

    padding: 13px 20px;

    display: flex;

    align-items: center;

    gap: 12px;

    border-bottom: 1px solid #edf0f3;
}


.nx-application:last-child {
    border-bottom: none;
}


.nx-application-details {
    flex: 1;

    min-width: 0;
}


.nx-application-details strong {
    display: block;

    color: #243b50;

    font-size: 11px;

    font-weight: 800;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}


.nx-application-details span {
    display: block;

    margin-top: 3px;

    color: #929eaa;

    font-size: 9px;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}


/* =========================================================
   COMPANY ICON
   ========================================================= */

.nx-company-icon {
    width: 45px;
    height: 45px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: #fff0ed;

    color: #ff6b5b;

    font-size: 14px;

    font-weight: 900;
}


.nx-company-icon.small {
    width: 38px;
    height: 38px;

    min-width: 38px;

    border-radius: 10px;

    font-size: 11px;
}


/* =========================================================
   STATUS
   ========================================================= */

.nx-status {
    flex-shrink: 0;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    padding: 5px 9px;

    border-radius: 20px;

    font-size: 8px;

    font-weight: 800;

    white-space: nowrap;
}


.nx-status-applied {
    background: #edf4f8;
    color: #356985;
}


.nx-status-shortlisted {
    background: #fff5df;
    color: #b7791f;
}


.nx-status-interview {
    background: #fff0ed;
    color: #df5c4c;
}


.nx-status-selected {
    background: #e7f7ef;
    color: #218a5d;
}


.nx-status-rejected {
    background: #ffeded;
    color: #d84e43;
}


.nx-status-offered {
    background: #f0eefa;
    color: #6651a7;
}


/* =========================================================
   DRIVES
   ========================================================= */

.nx-drives-card {
    margin-bottom: 20px;
}


.nx-drive-list {
    width: 100%;
}


.nx-drive {
    min-width: 0;
    min-height: 73px;

    padding: 15px 20px;

    display: flex;

    align-items: center;

    gap: 12px;

    border-bottom: 1px solid #edf0f3;
}


.nx-drive:last-child {
    border-bottom: none;
}


.nx-drive-details {
    flex: 1;

    min-width: 0;
}


.nx-drive-details strong {
    display: block;

    color: #243b50;

    font-size: 11px;

    font-weight: 800;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}


.nx-drive-details span {
    display: block;

    margin-top: 4px;

    color: #929faa;

    font-size: 9px;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}


.nx-drive-info {
    flex-shrink: 0;
}


.nx-drive-open {
    display: inline-flex;

    align-items: center;

    gap: 5px;

    color: #2a9567;

    font-size: 9px;

    font-weight: 700;

    white-space: nowrap;
}


.nx-drive-open i {
    font-size: 6px;

    color: #2bb673;
}


/* =========================================================
   EMPTY
   ========================================================= */

.nx-empty {
    min-height: 170px;

    padding: 30px 20px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    text-align: center;
}


.nx-empty-icon {
    width: 42px;
    height: 42px;

    margin-bottom: 10px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    background: #f0f4f7;

    color: #82919e;
}


.nx-empty strong {
    color: #4d6171;

    font-size: 11px;
}


.nx-empty span {
    max-width: 320px;

    margin-top: 5px;

    color: #9aa6b0;

    font-size: 9px;

    line-height: 1.5;
}


/* =========================================================
   QUICK ACCESS
   ========================================================= */

.nx-quick-actions {
    margin-bottom: 20px;
}


.nx-quick-heading {
    margin-bottom: 12px;
}


.nx-quick-heading h2 {
    margin: 5px 0 0;

    color: #19344b;

    font-size: 15px;

    font-weight: 800;
}


.nx-quick-grid {
    display: grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap: 13px;
}


.nx-quick-card {
    min-width: 0;
    min-height: 92px;

    padding: 15px;

    display: grid;

    grid-template-columns:
        38px
        minmax(0, 1fr)
        15px;

    align-items: center;

    gap: 11px;

    border: 1px solid #e3e9ee;

    border-radius: 13px;

    background: #ffffff;

    color: #243b50;

    cursor: pointer;

    text-align: left;

    box-shadow:
        0 4px 13px rgba(28,49,69,0.035);

    transition: all 0.2s ease;
}


.nx-quick-card:hover {
    transform: translateY(-3px);

    border-color: #ffcfc8;

    box-shadow:
        0 9px 22px rgba(28,49,69,0.08);
}


.nx-quick-card > i {
    color: #a0acb5;

    font-size: 12px;
}


.nx-quick-icon {
    width: 38px;
    height: 38px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 10px;

    font-size: 15px;
}


.nx-quick-icon.blue {
    background: #edf5fa;
    color: #2d6688;
}


.nx-quick-icon.orange {
    background: #fff0ed;
    color: #ff6b5b;
}


.nx-quick-icon.green {
    background: #e8f7ef;
    color: #249866;
}


.nx-quick-icon.purple {
    background: #f1eff9;
    color: #6b5a9e;
}


.nx-quick-icon.coral {
    background: #fff0ed;
    color: #ff6b5b;
}


.nx-quick-card strong {
    display: block;

    color: #30485c;

    font-size: 10px;

    font-weight: 800;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}


.nx-quick-card span {
    display: block;

    margin-top: 4px;

    color: #98a4ae;

    font-size: 8px;

    line-height: 1.3;
}


/* =========================================================
   PIPELINE
   ========================================================= */

.nx-pipeline-grid {
    padding: 25px;

    display: grid;

    grid-template-columns:
        minmax(90px, 1fr)
        25px
        minmax(90px, 1fr)
        25px
        minmax(90px, 1fr)
        25px
        minmax(90px, 1fr)
        25px
        minmax(90px, 1fr);

    align-items: center;

    gap: 8px;
}


.nx-pipeline-item {
    min-width: 0;

    padding: 15px 8px;

    display: flex;

    flex-direction: column;

    align-items: center;

    text-align: center;
}


.nx-pipeline-icon {
    width: 42px;
    height: 42px;

    margin-bottom: 9px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    font-size: 15px;
}


.nx-pipeline-icon.blue {
    background: #edf5fa;
    color: #2d6688;
}


.nx-pipeline-icon.orange {
    background: #fff5df;
    color: #b7791f;
}


.nx-pipeline-icon.purple {
    background: #f1eff9;
    color: #6b5a9e;
}


.nx-pipeline-icon.green {
    background: #e8f7ef;
    color: #249866;
}


.nx-pipeline-icon.coral {
    background: #fff0ed;
    color: #ff6b5b;
}


.nx-pipeline-item strong {
    color: #19344b;

    font-size: 21px;

    font-weight: 800;
}


.nx-pipeline-item span {
    margin-top: 4px;

    color: #8998a5;

    font-size: 9px;
}


.nx-pipeline-arrow {
    display: flex;

    align-items: center;
    justify-content: center;

    color: #b5c0c8;

    font-size: 13px;
}


/* =========================================================
   EVALUATIONS
   ========================================================= */

.nx-evaluation-card {
    margin-bottom: 20px;
}


.nx-evaluation-list {
    width: 100%;
}


.nx-evaluation-item {
    min-width: 0;

    min-height: 72px;

    padding: 15px 20px;

    display: flex;

    align-items: center;

    gap: 13px;

    border-bottom: 1px solid #edf0f3;
}


.nx-evaluation-item:last-child {
    border-bottom: none;
}


.nx-evaluation-icon {
    width: 40px;
    height: 40px;

    min-width: 40px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: #fff0ed;

    color: #ff6b5b;
}


.nx-evaluation-details {
    flex: 1;

    min-width: 0;
}


.nx-evaluation-details strong {
    display: block;

    color: #243b50;

    font-size: 11px;

    font-weight: 800;
}


.nx-evaluation-details span {
    display: block;

    margin-top: 4px;

    color: #929eaa;

    font-size: 9px;
}


.nx-evaluate-btn {
    flex-shrink: 0;

    padding: 8px 12px;

    display: inline-flex;

    align-items: center;

    gap: 6px;

    border: 1px solid #ffd0c9;

    border-radius: 8px;

    background: #fff0ed;

    color: #e45d4d;

    font-size: 9px;

    font-weight: 800;

    cursor: pointer;
}


.nx-evaluate-btn:hover {
    background: #ff6b5b;

    color: #ffffff;

    border-color: #ff6b5b;
}


/* =========================================================
   ANALYTICS
   ========================================================= */

.nx-analytics-card {
    margin-bottom: 20px;
}


.nx-analytics-caption {
    color: #94a1ac;

    font-size: 9px;
}


.nx-analytics-caption i {
    color: #ff6b5b;
}


.nx-analytics-grid {
    padding: 25px;

    display: grid;

    grid-template-columns:
        minmax(250px, 0.75fr)
        minmax(300px, 1.25fr);

    gap: 35px;

    align-items: center;
}


.nx-donut-section {
    display: flex;

    align-items: center;

    gap: 22px;
}


.nx-donut {
    width: 145px;
    height: 145px;

    position: relative;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background:
        conic-gradient(
            #ff6b5b 0deg 100deg,
            #2d6688 100deg 180deg,
            #2bb673 180deg 245deg,
            #f2a93b 245deg 300deg,
            #dfe5e9 300deg 360deg
        );
}


.nx-donut::before {
    content: "";

    position: absolute;

    width: 101px;
    height: 101px;

    border-radius: 50%;

    background: #ffffff;
}


.nx-donut-center {
    position: relative;

    z-index: 2;

    display: flex;

    flex-direction: column;

    align-items: center;
}


.nx-donut-center strong {
    color: #172b3f;

    font-size: 25px;

    font-weight: 900;
}


.nx-donut-center span {
    margin-top: 2px;

    color: #99a5ae;

    font-size: 9px;
}


.nx-status-breakdown {
    display: flex;

    flex-direction: column;

    gap: 14px;
}


.nx-status-row {
    width: 100%;
}


.nx-status-row-top {
    display: flex;

    align-items: center;

    justify-content: space-between;

    margin-bottom: 7px;
}


.nx-status-row-top span {
    display: flex;

    align-items: center;

    gap: 7px;

    color: #667987;

    font-size: 10px;
}


.nx-status-row-top strong {
    color: #30475b;

    font-size: 10px;
}


.nx-status-dot {
    width: 7px;
    height: 7px;

    display: inline-block;

    border-radius: 50%;
}


.nx-status-dot.applied {
    background: #ff6b5b;
}


.nx-status-dot.shortlisted {
    background: #f2a93b;
}


.nx-status-dot.interview {
    background: #2d6688;
}


.nx-status-dot.selected {
    background: #2bb673;
}


.nx-status-dot.rejected {
    background: #d9534f;
}


.nx-progress {
    width: 100%;

    height: 6px;

    border-radius: 20px;

    background: #edf1f4;

    overflow: hidden;
}


.nx-progress-bar {
    height: 100%;

    min-width: 2px;

    border-radius: inherit;

    transition: width 0.4s ease;
}


.nx-progress-bar.applied {
    background: #ff6b5b;
}


.nx-progress-bar.shortlisted {
    background: #f2a93b;
}


.nx-progress-bar.interview {
    background: #2d6688;
}


.nx-progress-bar.selected {
    background: #2bb673;
}


.nx-progress-bar.rejected {
    background: #d9534f;
}


/* =========================================================
   ACTION PANEL
   ========================================================= */

.nexora-action-overlay {
    position: fixed;

    inset: 0;

    z-index: 9998;

    background: rgba(18,35,51,0.48);

    backdrop-filter: blur(3px);
}


.nexora-action-panel {
    position: fixed;

    top: 0;
    right: 0;

    z-index: 9999;

    width: min(450px, 92vw);

    height: 100vh;

    display: flex;

    flex-direction: column;

    background: #ffffff;

    box-shadow:
        -15px 0 40px rgba(17,35,51,0.18);

    animation: nxPanelIn 0.25s ease;
}


@keyframes nxPanelIn {

    from {
        transform: translateX(100%);
    }

    to {
        transform: translateX(0);
    }
}


.nx-action-header {
    min-height: 82px;

    padding: 14px 22px;

    position: relative;

    display: flex;

    flex-direction: column;

    justify-content: center;

    border-bottom: 1px solid #e8edf1;
}


.nx-action-eyebrow {
    color: #ff6b5b;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: 1.5px;
}


.nx-action-header h2 {
    margin: 4px 0 0;

    color: #19344b;

    font-size: 18px;

    font-weight: 800;
}


.nx-action-close {
    position: absolute;

    top: 22px;
    right: 20px;

    width: 35px;
    height: 35px;

    display: flex;

    align-items: center;
    justify-content: center;

    border: none;

    border-radius: 9px;

    background: #f0f3f5;

    color: #687986;

    cursor: pointer;
}


.nx-action-body {
    flex: 1;

    overflow-y: auto;

    padding: 24px;

    background: #f5f7f9;
}


.nx-action-content {
    padding: 25px;

    border-radius: 15px;

    background: #ffffff;

    border: 1px solid #e4e9ef;
}


.nx-action-icon {
    width: 48px;
    height: 48px;

    margin-bottom: 18px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 13px;

    background: #fff0ed;

    color: #ff6b5b;

    font-size: 19px;
}


.nx-action-content h3 {
    margin: 0;

    color: #19344b;

    font-size: 18px;

    font-weight: 800;
}


.nx-action-content p {
    margin: 10px 0 0;

    color: #718291;

    font-size: 12px;

    line-height: 1.7;
}


.nx-action-primary {
    width: 100%;

    margin-top: 22px;

    padding: 12px 18px;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 8px;

    border: none;

    border-radius: 9px;

    background: #ff6b5b;

    color: #ffffff;

    font-size: 11px;

    font-weight: 800;

    cursor: pointer;
}


/* =========================================================
   RESPONSIVE - 1200
   ========================================================= */

@media (max-width: 1200px) {

    .nexora-main {
        padding: 35px;
    }


    .nx-dashboard {
        padding: 20px 15px 40px;
    }


    .nx-kpi-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }


    .nx-quick-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }


    .nx-pipeline-grid {
        grid-template-columns:
            repeat(5, minmax(0, 1fr));

        gap: 5px;
    }


    .nx-pipeline-arrow {
        display: none;
    }

}


/* =========================================================
   RESPONSIVE - 1000
   ========================================================= */

@media (max-width: 1000px) {

    .nexora-main {
        padding: 25px;
    }


    .nx-content-grid {
        grid-template-columns: 1fr;
    }


    .nx-analytics-grid {
        grid-template-columns: 1fr;
    }


    .nx-donut-section {
        justify-content: center;
    }


    .nx-pipeline-grid {
        grid-template-columns:
            repeat(3, minmax(0, 1fr));
    }

}


/* =========================================================
   RESPONSIVE - 750
   ========================================================= */

@media (max-width: 750px) {

    .nexora-main {
        padding: 15px;
    }


    .nx-dashboard {
        padding: 12px 5px 30px;
    }


    .nx-welcome {
        min-height: auto;

        padding: 27px;

        align-items: flex-start;

        flex-direction: column;
    }


    .nx-primary-btn {
        margin-top: 18px;

        margin-left: 0;
    }


    .nx-journey-card {
        overflow-x: auto;
    }


    .nx-journey-wrapper {
        min-width: 650px;
    }


    .nx-pipeline-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));

        gap: 5px;
    }


    .nx-pipeline-arrow {
        display: none;
    }

}


/* =========================================================
   RESPONSIVE - 560
   ========================================================= */

@media (max-width: 560px) {

    .nexora-main {
        padding: 10px;
    }


    .nx-dashboard {
        padding: 8px 3px 25px;
    }


    .nx-kpi-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));

        gap: 10px;
    }


    .nx-kpi-card {
        min-height: 100px;

        padding: 13px;

        gap: 9px;
    }


    .nx-kpi-icon {
        width: 39px;
        height: 39px;

        min-width: 39px;

        font-size: 15px;
    }


    .nx-kpi-info strong {
        font-size: 21px;
    }


    .nx-kpi-info span {
        font-size: 9px;
    }


    .nx-kpi-info small {
        font-size: 8px;
    }


    .nx-quick-grid {
        grid-template-columns: 1fr;
    }


    .nx-pipeline-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));

        padding: 15px;
    }


    .nx-donut-section {
        flex-direction: column;

        justify-content: center;

        text-align: center;
    }


    .nx-drive {
        padding: 13px;
    }


    .nx-drive-info {
        display: none;
    }


    .nx-application {
        padding: 12px;
    }


    .nx-status {
        padding: 4px 7px;

        font-size: 7px;
    }


    .nx-evaluate-btn {
        padding: 7px 9px;
    }

}


/* =========================================================
   RESPONSIVE - 420
   ========================================================= */

@media (max-width: 420px) {

    .nx-kpi-grid {
        grid-template-columns: 1fr;
    }


    .nx-welcome {
        padding: 23px;
    }


    .nx-welcome h1 {
        font-size: 25px;
    }


    .nx-welcome p {
        font-size: 11px;
    }


    .nx-kpi-card {
        min-height: 90px;
    }


    .nx-pipeline-grid {
        grid-template-columns: 1fr 1fr;
    }


    .nx-card-header {
        align-items: flex-start;

        flex-direction: column;

        gap: 8px;
    }


    .nx-view-btn {
        align-self: flex-start;
    }


    .nx-application {
        align-items: flex-start;
    }


    .nx-application .nx-status {
        align-self: center;
    }


    .nx-evaluation-item {
        align-items: flex-start;

        flex-wrap: wrap;
    }


    .nx-evaluate-btn {
        margin-left: 53px;
    }


    .nx-quick-card {
        min-height: 85px;
    }

}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

button:focus-visible {
    outline: 2px solid #ff6b5b;

    outline-offset: 2px;
}


@media (prefers-reduced-motion: reduce) {

    *,
    *::before,
    *::after {

        animation-duration: 0.01ms !important;

        transition-duration: 0.01ms !important;

    }

}

sp_widget.script:
(function() { 

    /* ========================================================= 
       NEXORA COMMON DASHBOARD 
       ROLE-BASED SERVER SCRIPT 

       ROLES 
       1. Placement Admin 
       2. Placement Officer 
       3. Interviewer 
       4. Student 

       INTERVIEW LOGIC 
       ------------------------- 
       Scheduled               -> NOT Pending
       In Progress             -> NOT Pending
       Completed + no Result   -> PENDING EVALUATION
       Completed + Pass        -> SELECTED
       Completed + Fail        -> EVALUATED / NOT SELECTED
       ========================================================= */ 


    /* ========================================================= 
       DEFAULT USER DATA 
       ========================================================= */ 

    data.studentName = 'User'; 
    data.userEmail = ''; 
    data.username = ''; 
    data.userActive = true; 

    data.role = 'User'; 
    data.roleLabel = 'User'; 

    data.homePage = 'dashboard'; 


    /* ========================================================= 
       COMMON DATA 
       ========================================================= */ 

    data.applications = []; 
    data.interviews = []; 
    data.drives = []; 
    data.pendingEvaluations = []; 


    /* ========================================================= 
       STUDENT DATA 
       ========================================================= */ 

    data.applicationCount = 0; 
    data.interviewCount = 0; 
    data.offerCount = 0; 
    data.selectedCount = 0; 
    data.shortlistedCount = 0; 

    data.upcomingInterview = null; 

    data.recentApplications = []; 
    data.availableDrives = []; 

    data.applicationStatusChart = { 

        applied: 0, 
        shortlisted: 0, 
        interview: 0, 
        selected: 0, 
        rejected: 0, 
        offered: 0, 

        total: 0, 

        appliedPercent: 0, 
        shortlistedPercent: 0, 
        interviewPercent: 0, 
        selectedPercent: 0, 
        rejectedPercent: 0, 
        offeredPercent: 0 
    }; 

    data.driveChart = []; 


    /* ========================================================= 
       STAFF DATA 
       ========================================================= */ 

    data.staff = { 

        studentCount: 0, 
        companyCount: 0, 

        driveCount: 0, 
        activeDriveCount: 0, 

        applicationCount: 0, 
        interviewCount: 0, 

        selectedCount: 0, 
        offeredCount: 0, 
        shortlistedCount: 0, 

        applications: [], 
        activeDrives: [], 
        drives: [], 
        upcomingInterviews: [], 

        pipeline: { 

            applications: 0, 
            shortlisted: 0, 
            interview: 0, 
            selected: 0, 
            offered: 0, 
            rejected: 0 
        } 
    }; 


    /* ========================================================= 
       INTERVIEWER DATA 
       ========================================================= */ 

    data.interviewer = { 

        assignedInterviews: 0, 

        interviewCount: 0, 

        assignedDriveCount: 0, 

        driveCount: 0, 

        pendingEvaluations: 0, 

        pendingEvaluationCount: 0, 

        completedEvaluations: 0, 

        selectedCandidateCount: 0, 

        assignedDrives: [], 

        drives: [], 

        applications: [], 

        interviews: [], 

        selectedCandidates: [], 

        pendingEvaluationsList: [], 

        recentEvaluations: [] 
    }; 


    /* ========================================================= 
       CURRENT USER 
       ========================================================= */ 

    var userId = gs.getUserID(); 

    if (!userId) { 
        return; 
    } 


    /* ========================================================= 
       USER INFORMATION 
       ========================================================= */ 

    var userGR = 
        new GlideRecord('sys_user'); 

    if (userGR.get(userId)) { 

        data.studentName = 
            userGR.getDisplayValue('name') || 'User'; 

        data.userEmail = 
            userGR.getValue('email') || ''; 

        data.username = 
            userGR.getValue('user_name') || ''; 

        data.userActive = 
            userGR.getValue('active') == 'true'; 
    } 


    /* ========================================================= 
       ROLE DETECTION 
       ========================================================= */ 

    var isAdmin = 
        gs.hasRole( 
            'x_snc_college_pl_0.placement_admin' 
        ); 

    var isOfficer = 
        gs.hasRole( 
            'x_snc_college_pl_0.placement_officer' 
        ); 

    var isInterviewer = 
        gs.hasRole( 
            'x_snc_college_pl_0.interviewer' 
        ); 

    var isStudent = 
        gs.hasRole( 
            'x_snc_college_pl_0.student_user' 
        ); 


    /* ========================================================= 
       ROLE ROUTING 
       ========================================================= */ 

    if (isAdmin) { 

        data.role = 'Placement Admin'; 
        data.roleLabel = 'Placement Admin'; 

        data.menuItems = getStaffMenu(); 

        loadStaffDashboard(); 

        return; 
    } 


    if (isOfficer) { 

        data.role = 'Placement Officer'; 
        data.roleLabel = 'Placement Officer'; 

        data.menuItems = getStaffMenu(); 

        loadStaffDashboard(); 

        return; 
    } 


    if (isInterviewer) { 

        data.role = 'Interviewer'; 
        data.roleLabel = 'Interviewer'; 

        data.menuItems = getInterviewerMenu(); 

        loadInterviewerDashboard(); 

        return; 
    } 


    if (isStudent) { 

        data.role = 'Student'; 
        data.roleLabel = 'Student'; 

        data.menuItems = getStudentMenu(); 

        loadStudentDashboard(userId); 

        return; 
    } 


    /* ========================================================= 
       FALLBACK 
       ========================================================= */ 

    data.menuItems = [ 

        { 
            label: 'Dashboard', 
            page: 'dashboard', 
            icon: 'fa-home' 
        } 

    ]; 


    /* ========================================================= 
       STUDENT MENU 
       ========================================================= */ 

    function getStudentMenu() { 

        return [ 

            { 
                label: 'Dashboard', 
                page: 'dashboard', 
                icon: 'fa-home' 
            }, 

            { 
                label: 'Placement Drives', 
                page: 'placement_drives', 
                icon: 'fa-briefcase' 
            }, 

            { 
                label: 'My Applications', 
                page: 'my_applications', 
                icon: 'fa-file-text' 
            }, 

            { 
                label: 'Interviews', 
                page: 'stu_interviews', 
                icon: 'fa-comments' 
            }, 

            { 
                label: 'Offer Letter', 
                page: 'offer_letter', 
                icon: 'fa-trophy' 
            }, 

            { 
                label: 'Documents', 
                page: 'my_documents', 
                icon: 'fa-folder-open' 
            } 

        ]; 
    } 


    /* ========================================================= 
       STAFF MENU 
       ========================================================= */ 

    function getStaffMenu() { 

        return [ 

            { 
                label: 'Dashboard', 
                page: 'dashboard', 
                icon: 'fa-home' 
            }, 

            { 
                label: 'Students', 
                page: 'students', 
                icon: 'fa-users' 
            }, 

            { 
                label: 'Companies', 
                page: 'companies', 
                icon: 'fa-building-o' 
            }, 

            { 
                label: 'Placement Drives', 
                page: 'placement_drives', 
                icon: 'fa-briefcase' 
            }, 

            { 
                label: 'Applications', 
                page: 'applications', 
                icon: 'fa-file-text' 
            }, 

            { 
                label: 'Interviews', 
                page: 'interview_management', 
                icon: 'fa-comments' 
            }, 

            { 
                label: 'Interview Evaluation', 
                page: 'interview_evaluation', 
                icon: 'fa-check-square-o' 
            } 

        ]; 
    } 


    /* ========================================================= 
       INTERVIEWER MENU 
       ========================================================= */ 

    function getInterviewerMenu() { 

        return [ 

            { 
                label: 'Dashboard', 
                page: 'dashboard', 
                icon: 'fa-home' 
            }, 

            { 
                label: 'Placement Drives', 
                page: 'placement_drives', 
                icon: 'fa-briefcase' 
            }, 

            { 
                label: 'Applications', 
                page: 'applications', 
                icon: 'fa-file-text' 
            }, 

            { 
                label: 'Interviews', 
                page: 'interviews', 
                icon: 'fa-comments' 
            }, 

            { 
                label: 'Interview Evaluation', 
                page: 'interview_evaluation', 
                icon: 'fa-check-square-o' 
            } 

        ]; 
    } 


    /* ========================================================= 
       STUDENT DASHBOARD 
       ========================================================= */ 

    function loadStudentDashboard(currentUserId) { 

        var studentId = ''; 

        var studentGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_student' 
            ); 

        studentGR.addQuery( 
            'user', 
            currentUserId 
        ); 

        studentGR.setLimit(1); 

        studentGR.query(); 

        if (studentGR.next()) { 

            studentId = 
                studentGR.getUniqueValue(); 
        } 

        if (!studentId) { 
            return; 
        } 


        /* ===================================================== 
           APPLICATIONS 
           ===================================================== */ 

        var applicationGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_application' 
            ); 

        applicationGR.addQuery( 
            'student', 
            studentId 
        ); 

        applicationGR.query(); 

        while (applicationGR.next()) { 

            data.applicationCount++; 

            var status = 
                applicationGR.getDisplayValue( 
                    'status' 
                ) || 'Applied'; 

            var normalized = 
                normalizeStatus(status); 

            if (normalized == 'applied') { 

                data.applicationStatusChart.applied++; 

            } else if (normalized == 'shortlisted') { 

                data.applicationStatusChart.shortlisted++; 

            } else if ( 
                normalized.indexOf('interview') != -1 
            ) { 

                data.applicationStatusChart.interview++; 

            } else if (normalized == 'selected') { 

                data.applicationStatusChart.selected++; 

            } else if (normalized == 'rejected') { 

                data.applicationStatusChart.rejected++; 

            } else if (normalized == 'offered') { 

                data.applicationStatusChart.offered++; 
            } 

            if ( 
                data.recentApplications.length < 5 
            ) { 

                data.recentApplications.push( 
                    buildApplicationObject( 
                        applicationGR 
                    ) 
                ); 
            } 
        } 

        data.applicationStatusChart.total = 
            data.applicationCount; 

        data.selectedCount = 
            data.applicationStatusChart.selected; 

        data.shortlistedCount = 
            data.applicationStatusChart.shortlisted; 

        calculateStudentPercentages(); 


        /* ===================================================== 
           OFFER LETTERS 
           ===================================================== */ 

        var offerGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_offer_letter' 
            ); 

        if (offerGR.isValid()) { 

            offerGR.addQuery( 
                'student', 
                studentId 
            ); 

            offerGR.query(); 

            data.offerCount = 
                offerGR.getRowCount(); 
        } 


        /* ===================================================== 
           AVAILABLE DRIVES 
           ===================================================== */ 

        var driveGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_placement_drive' 
            ); 

        driveGR.orderBy('drive_date'); 

        driveGR.setLimit(8); 

        driveGR.query(); 

        while (driveGR.next()) { 

            data.availableDrives.push( 
                buildDriveObject(driveGR) 
            ); 
        } 


        /* ===================================================== 
           STUDENT INTERVIEWS 
           ===================================================== */ 

        loadStudentInterviews(studentId); 
    } 


    /* ========================================================= 
       STAFF DASHBOARD 
       ========================================================= */ 

    function loadStaffDashboard() { 

        var studentGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_student' 
            ); 

        studentGR.query(); 

        data.staff.studentCount = 
            studentGR.getRowCount(); 


        var companyGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_company' 
            ); 

        if (companyGR.isValid()) { 

            companyGR.query(); 

            data.staff.companyCount = 
                companyGR.getRowCount(); 
        } 


        /* ===================================================== 
           DRIVES 
           ===================================================== */ 

        var driveGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_placement_drive' 
            ); 

        driveGR.query(); 

        while (driveGR.next()) { 

            data.staff.driveCount++; 

            var driveObject = 
                buildDriveObject(driveGR); 

            var normalizedStatus = 
                normalizeStatus( 
                    driveObject.status 
                ); 

            if ( 
                normalizedStatus == 'open' || 
                normalizedStatus == 'active' 
            ) { 

                data.staff.activeDriveCount++; 

                if ( 
                    data.staff.activeDrives.length < 8 
                ) { 

                    data.staff.activeDrives.push( 
                        driveObject 
                    ); 
                } 
            } 

            if ( 
                data.staff.drives.length < 10 
            ) { 

                data.staff.drives.push( 
                    driveObject 
                ); 
            } 
        } 


        /* ===================================================== 
           APPLICATIONS 
           ===================================================== */ 

        var applicationGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_application' 
            ); 

        applicationGR.orderByDesc( 
            'sys_created_on' 
        ); 

        applicationGR.query(); 

        while (applicationGR.next()) { 

            data.staff.applicationCount++; 

            var applicationStatus = 
                applicationGR.getDisplayValue( 
                    'status' 
                ) || 'Applied'; 

            var normalizedApplicationStatus = 
                normalizeStatus( 
                    applicationStatus 
                ); 

            data.staff.pipeline.applications++; 

            if ( 
                normalizedApplicationStatus == 
                'shortlisted' 
            ) { 

                data.staff.shortlistedCount++; 

                data.staff.pipeline.shortlisted++; 
            } 

            if ( 
                normalizedApplicationStatus.indexOf( 
                    'interview' 
                ) != -1 
            ) { 

                data.staff.pipeline.interview++; 
            } 

            if ( 
                normalizedApplicationStatus == 
                'selected' 
            ) { 

                data.staff.selectedCount++; 

                data.staff.pipeline.selected++; 
            } 

            if ( 
                normalizedApplicationStatus == 
                'offered' 
            ) { 

                data.staff.pipeline.offered++; 
            } 

            if ( 
                normalizedApplicationStatus == 
                'rejected' 
            ) { 

                data.staff.pipeline.rejected++; 
            } 

            if ( 
                data.staff.applications.length < 10 
            ) { 

                data.staff.applications.push( 
                    buildApplicationObject( 
                        applicationGR 
                    ) 
                ); 
            } 
        } 


        loadStaffInterviews(); 


        var offerGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_offer_letter' 
            ); 

        if (offerGR.isValid()) { 

            offerGR.query(); 

            data.staff.offeredCount = 
                offerGR.getRowCount(); 
        } 

        data.applications = 
            data.staff.applications; 

        data.interviews = 
            data.staff.upcomingInterviews; 

        data.drives = 
            data.staff.drives; 
    } 


    /* ========================================================= 
       STAFF INTERVIEWS 
       ========================================================= */ 

    function loadStaffInterviews() { 

        var interviewGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_interview' 
            ); 

        if (!interviewGR.isValid()) { 
            return; 
        } 

        interviewGR.orderByDesc( 
            'sys_created_on' 
        ); 

        interviewGR.query(); 

        while (interviewGR.next()) { 

            data.staff.interviewCount++; 

            var interviewObject = 
                buildInterviewObject( 
                    interviewGR 
                ); 

            var status = 
                normalizeStatus( 
                    interviewObject.status 
                ); 

            if ( 
                status == 'scheduled' || 
                status == 'in progress' || 
                status == 'in_progress' 
            ) { 

                if ( 
                    data.staff.upcomingInterviews.length < 8 
                ) { 

                    data.staff.upcomingInterviews.push( 
                        interviewObject 
                    ); 
                } 
            } 
        } 
    } 


    /* ========================================================= 
       INTERVIEWER DASHBOARD 
       ========================================================= */ 

    function loadInterviewerDashboard() { 

        var interviewGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_interview' 
            ); 

        if (!interviewGR.isValid()) { 
            return; 
        } 


        var interviewerField = 
            findValidField( 
                interviewGR, 
                [ 
                    'interviewer', 
                    'assigned_to', 
                    'interviewer_user' 
                ] 
            ); 

        if (!interviewerField) { 
            return; 
        } 


        var driveField = 
            findValidField( 
                interviewGR, 
                [ 
                    'drive', 
                    'placement_drive' 
                ] 
            ); 


        var resultField = 
            findValidField( 
                interviewGR, 
                [ 
                    'result', 
                    'interview_result' 
                ] 
            ); 


        var feedbackField = 
            findValidField( 
                interviewGR, 
                [ 
                    'feedback', 
                    'interview_feedback' 
                ] 
            ); 


        /* ===================================================== 
           CURRENT INTERVIEWER ONLY 
           ===================================================== */ 

        interviewGR.addQuery( 
            interviewerField, 
            userId 
        ); 

        interviewGR.orderByDesc( 
            'sys_created_on' 
        ); 

        interviewGR.query(); 


        var assignedDriveIds = {}; 
        var assignedDriveIdList = []; 


        while (interviewGR.next()) { 

            data.interviewer.assignedInterviews++; 


            /* ================================================= 
               DRIVE 
               ================================================= */ 

            var driveId = ''; 

            if (driveField) { 

                driveId = 
                    interviewGR.getValue( 
                        driveField 
                    ) || ''; 
            } 

            if ( 
                driveId && 
                !assignedDriveIds[driveId] 
            ) { 

                assignedDriveIds[driveId] = true; 

                assignedDriveIdList.push( 
                    driveId 
                ); 
            } 


            /* ================================================= 
               INTERVIEW STATUS 
               ================================================= */ 

            var interviewStatus = 
                getFirstValidValue( 
                    interviewGR, 
                    [ 
                        'status', 
                        'state' 
                    ] 
                ) || 'Scheduled'; 


            /* ================================================= 
               RESULT 
               ================================================= */ 

            var result = ''; 

            if (resultField) { 

                result = 
                    getFirstValidValue( 
                        interviewGR, 
                        [ 
                            resultField 
                        ] 
                    ); 
            } 


            /* ================================================= 
               FEEDBACK 
               ================================================= */ 

            var feedback = ''; 

            if (feedbackField) { 

                feedback = 
                    getFirstValidValue( 
                        interviewGR, 
                        [ 
                            feedbackField 
                        ] 
                    ); 
            } 


            /* ================================================= 
               BUILD INTERVIEW DATA 
               ================================================= */ 

            var interviewData = 
                buildInterviewerInterviewObject( 
                    interviewGR, 
                    driveId, 
                    interviewStatus, 
                    result, 
                    feedback 
                ); 


            if (!interviewData) { 
                continue; 
            } 


            data.interviewer.interviews.push( 
                interviewData 
            ); 


            /* ================================================= 
               CORRECT EVALUATION LOGIC 

               Scheduled 
                    -> NOT pending 

               In Progress 
                    -> NOT pending 

               Completed + no Result 
                    -> PENDING 

               Completed + Pass 
                    -> EVALUATED / SELECTED 

               Completed + Fail 
                    -> EVALUATED / NOT SELECTED 
               ================================================= */ 

            if ( 
                interviewData.hasValidApplication 
            ) { 

                var normalizedStatus = 
                    normalizeStatus( 
                        interviewStatus 
                    ); 

                var normalizedResult = 
                    normalizeStatus( 
                        result 
                    ); 

                var completedStatus = 
                    normalizedStatus == 'completed' || 
                    normalizedStatus == 'complete'; 

                var hasResult = 
                    !!normalizedResult; 


                /* ================================================= 
                   PENDING ONLY WHEN:

                   STATUS = COMPLETED
                   AND
                   RESULT IS EMPTY
                   ================================================= */ 

                if ( 
                    completedStatus && 
                    !hasResult 
                ) { 

                    data.interviewer.pendingEvaluations++; 

                    data.interviewer.pendingEvaluationCount++; 

                    if ( 
                        data.interviewer.pendingEvaluationsList.length < 8 
                    ) { 

                        data.interviewer.pendingEvaluationsList.push( 
                            interviewData 
                        ); 
                    } 

                } else if ( 
                    completedStatus && 
                    hasResult 
                ) { 

                    /* 
                     * Result exists.
                     * Therefore evaluation is complete.
                     */ 

                    data.interviewer.completedEvaluations++; 

                    if ( 
                        data.interviewer.recentEvaluations.length < 6 
                    ) { 

                        data.interviewer.recentEvaluations.push( 
                            interviewData 
                        ); 
                    } 
                } 
            } 
        } 


        /* ===================================================== 
           COUNTS 
           ===================================================== */ 

        data.interviewer.assignedDriveCount = 
            assignedDriveIdList.length; 

        data.interviewer.driveCount = 
            assignedDriveIdList.length; 

        data.interviewer.interviewCount = 
            data.interviewer.assignedInterviews; 


        /* ===================================================== 
           ASSIGNED DRIVES 
           ===================================================== */ 

        loadInterviewerAssignedDrives( 
            assignedDriveIdList 
        ); 

        data.interviewer.drives = 
            data.interviewer.assignedDrives; 


        /* ===================================================== 
           APPLICATIONS 
           ===================================================== */ 

        loadInterviewerApplications( 
            assignedDriveIdList 
        ); 


        /* ===================================================== 
           SELECTED CANDIDATES 
           ===================================================== */ 

        loadInterviewerSelectedCandidates( 
            assignedDriveIdList 
        ); 


        /* ===================================================== 
           TOP LEVEL ALIASES 
           ===================================================== */ 

        data.applications = 
            data.interviewer.applications; 

        data.interviews = 
            data.interviewer.interviews; 

        data.drives = 
            data.interviewer.assignedDrives; 

        data.pendingEvaluations = 
            data.interviewer.pendingEvaluationsList; 
    } 


    /* ========================================================= 
       BUILD INTERVIEWER INTERVIEW OBJECT 
       ========================================================= */ 

    function buildInterviewerInterviewObject( 
        interviewGR, 
        driveId, 
        interviewStatus, 
        result, 
        feedback 
    ) { 

        var applicationGR = 
            resolveInterviewApplication( 
                interviewGR, 
                driveId 
            ); 

        var hasValidApplication = 
            !!applicationGR; 

        var studentName = ''; 
        var studentId = ''; 
        var applicationId = ''; 


        /* ===================================================== 
           STUDENT FROM APPLICATION 
           ===================================================== */ 

        if (applicationGR) { 

            applicationId = 
                applicationGR.getUniqueValue(); 

            studentId = 
                applicationGR.getValue( 
                    'student' 
                ) || ''; 

            if (studentId) { 

                studentName = 
                    getStudentName( 
                        studentId 
                    ); 
            } 
        } 


        /* ===================================================== 
           FALLBACK INTERVIEW.STUDENT 
           ===================================================== */ 

        if ( 
            !studentName && 
            interviewGR.isValidField('student') 
        ) { 

            studentId = 
                interviewGR.getValue( 
                    'student' 
                ) || ''; 

            if (studentId) { 

                studentName = 
                    getStudentName( 
                        studentId 
                    ); 
            } 
        } 


        if (!studentName) { 
            return null; 
        } 


        /* ===================================================== 
           COMPANY 
           ===================================================== */ 

        var company = 
            getFirstValidValue( 
                interviewGR, 
                [ 
                    'company' 
                ] 
            ); 


        /* ===================================================== 
           POSITION 
           ===================================================== */ 

        var position = 
            getFirstValidValue( 
                interviewGR, 
                [ 
                    'position', 
                    'job_role', 
                    'role' 
                ] 
            ); 


        /* ===================================================== 
           DRIVE INFORMATION 
           ===================================================== */ 

        var driveName = ''; 

        if (driveId) { 

            var driveGR = 
                new GlideRecord( 
                    'x_snc_college_pl_0_placement_drive' 
                ); 

            if (driveGR.get(driveId)) { 

                if (!company) { 

                    company = 
                        driveGR.getDisplayValue( 
                            'company' 
                        ); 
                } 

                if (!position) { 

                    position = 
                        getFirstValidValue( 
                            driveGR, 
                            [ 
                                'job_role', 
                                'position', 
                                'role' 
                            ] 
                        ); 
                } 

                driveName = 
                    getFirstValidValue( 
                        driveGR, 
                        [ 
                            'drive_name', 
                            'name' 
                        ] 
                    ); 
            } 
        } 


        if (!driveName) { 

            var driveField = 
                findValidField( 
                    interviewGR, 
                    [ 
                        'drive', 
                        'placement_drive' 
                    ] 
                ); 

            if (driveField) { 

                driveName = 
                    interviewGR.getDisplayValue( 
                        driveField 
                    ) || ''; 
            } 
        } 


        var normalizedResult = 
            normalizeStatus( 
                result 
            ); 


        return { 

            sys_id: 
                interviewGR.getUniqueValue(), 

            studentName: 
                studentName, 

            studentId: 
                studentId, 

            application: 
                applicationId, 

            hasValidApplication: 
                hasValidApplication, 

            company: 
                company || 'Company', 

            companyInitial: 
                getInitial( 
                    company || 'Company' 
                ), 

            drive: 
                driveName || 'Placement Drive', 

            driveName: 
                driveName || 'Placement Drive', 

            position: 
                position || 'Interview', 

            jobRole: 
                position || 'Interview', 

            date: 
                getFirstValidValue( 
                    interviewGR, 
                    [ 
                        'interview_date', 
                        'date' 
                    ] 
                ), 

            time: 
                getFirstValidValue( 
                    interviewGR, 
                    [ 
                        'interview_time', 
                        'time' 
                    ] 
                ), 

            status: 
                interviewStatus, 

            statusClass: 
                getStatusClass( 
                    interviewStatus 
                ), 

            result: 
                result || '', 

            normalizedResult: 
                normalizedResult, 

            feedback: 
                feedback || '', 

            isPassed: 
                normalizedResult == 'pass' 
        }; 
    } 


    /* ========================================================= 
       RESOLVE INTERVIEW APPLICATION 
       ========================================================= */ 

    function resolveInterviewApplication( 
        interviewGR, 
        driveId 
    ) { 

        if ( 
            interviewGR.isValidField( 
                'application' 
            ) 
        ) { 

            var directApplicationId = 
                interviewGR.getValue( 
                    'application' 
                ) || ''; 

            if (directApplicationId) { 

                var directApplicationGR = 
                    new GlideRecord( 
                        'x_snc_college_pl_0_application' 
                    ); 

                if ( 
                    directApplicationGR.get( 
                        directApplicationId 
                    ) 
                ) { 

                    return directApplicationGR; 
                } 
            } 
        } 


        var studentId = ''; 

        if ( 
            interviewGR.isValidField( 
                'student' 
            ) 
        ) { 

            studentId = 
                interviewGR.getValue( 
                    'student' 
                ) || ''; 
        } 

        if ( 
            !studentId || 
            !driveId 
        ) { 

            return null; 
        } 


        var applicationGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_application' 
            ); 

        applicationGR.addQuery( 
            'student', 
            studentId 
        ); 

        applicationGR.addQuery( 
            'drive', 
            driveId 
        ); 

        applicationGR.orderByDesc( 
            'sys_created_on' 
        ); 

        applicationGR.setLimit(1); 

        applicationGR.query(); 

        if (applicationGR.next()) { 

            return applicationGR; 
        } 

        return null; 
    } 


    /* ========================================================= 
       GET STUDENT NAME 
       ========================================================= */ 

    function getStudentName( 
        studentId 
    ) { 

        if (!studentId) { 
            return ''; 
        } 

        var studentGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_student' 
            ); 

        if (!studentGR.get(studentId)) { 
            return ''; 
        } 

        var name = 
            studentGR.getDisplayValue( 
                'name' 
            ); 

        if (name) { 
            return name; 
        } 

        name = 
            studentGR.getDisplayValue( 
                'user' 
            ); 

        if (name) { 
            return name; 
        } 

        return ''; 
    } 


    /* ========================================================= 
       INTERVIEWER ASSIGNED DRIVES 
       ========================================================= */ 

    function loadInterviewerAssignedDrives( 
        assignedDriveIdList 
    ) { 

        if ( 
            !assignedDriveIdList || 
            assignedDriveIdList.length === 0 
        ) { 

            return; 
        } 

        var driveGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_placement_drive' 
            ); 

        driveGR.addQuery( 
            'sys_id', 
            'IN', 
            assignedDriveIdList.join(',') 
        ); 

        driveGR.orderByDesc( 
            'sys_created_on' 
        ); 

        driveGR.query(); 

        while (driveGR.next()) { 

            data.interviewer.assignedDrives.push( 
                buildDriveObject( 
                    driveGR 
                ) 
            ); 
        } 
    } 


    /* ========================================================= 
       INTERVIEWER APPLICATIONS 
       ========================================================= */ 

    function loadInterviewerApplications( 
        assignedDriveIdList 
    ) { 

        if ( 
            !assignedDriveIdList || 
            assignedDriveIdList.length === 0 
        ) { 

            return; 
        } 

        var applicationGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_application' 
            ); 

        applicationGR.addQuery( 
            'drive', 
            'IN', 
            assignedDriveIdList.join(',') 
        ); 

        applicationGR.orderByDesc( 
            'sys_created_on' 
        ); 

        applicationGR.query(); 

        while (applicationGR.next()) { 

            data.interviewer.applications.push( 
                buildApplicationObject( 
                    applicationGR 
                ) 
            ); 
        } 
    } 


    /* ========================================================= 
       SELECTED CANDIDATES 

       STRICT RULE:

       Interview Status = Completed
       AND
       Interview Result = Pass

       ========================================================= */ 

    function loadInterviewerSelectedCandidates( 
        assignedDriveIdList 
    ) { 

        data.interviewer.selectedCandidates = []; 

        data.interviewer.selectedCandidateCount = 0; 

        if ( 
            !assignedDriveIdList || 
            assignedDriveIdList.length === 0 
        ) { 

            return; 
        } 

        var selectedStudents = {}; 

        var interviewGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_interview' 
            ); 

        if (!interviewGR.isValid()) { 
            return; 
        } 


        /* ===================================================== 
           RESULT FIELD 
           ===================================================== */ 

        var resultField = 
            findValidField( 
                interviewGR, 
                [ 
                    'result', 
                    'interview_result' 
                ] 
            ); 

        if (!resultField) { 
            return; 
        } 


        /* ===================================================== 
           STATUS FIELD 
           ===================================================== */ 

        var statusField = 
            findValidField( 
                interviewGR, 
                [ 
                    'status', 
                    'state' 
                ] 
            ); 

        if (!statusField) { 
            return; 
        } 


        /* ===================================================== 
           INTERVIEWER FIELD 
           ===================================================== */ 

        var interviewerField = 
            findValidField( 
                interviewGR, 
                [ 
                    'interviewer', 
                    'assigned_to', 
                    'interviewer_user' 
                ] 
            ); 

        if (interviewerField) { 

            interviewGR.addQuery( 
                interviewerField, 
                userId 
            ); 
        } 


        /* ===================================================== 
           DRIVE FIELD 
           ===================================================== */ 

        var driveField = 
            findValidField( 
                interviewGR, 
                [ 
                    'drive', 
                    'placement_drive' 
                ] 
            ); 

        if ( 
            driveField && 
            assignedDriveIdList.length > 0 
        ) { 

            interviewGR.addQuery( 
                driveField, 
                'IN', 
                assignedDriveIdList.join(',') 
            ); 
        } 


        interviewGR.query(); 


        /* ===================================================== 
           LOOP 
           ===================================================== */ 

        while (interviewGR.next()) { 

            var interviewStatus = 
                normalizeStatus( 
                    interviewGR.getDisplayValue( 
                        statusField 
                    ) || 
                    interviewGR.getValue( 
                        statusField 
                    ) 
                ); 

            var interviewResult = 
                normalizeStatus( 
                    interviewGR.getDisplayValue( 
                        resultField 
                    ) || 
                    interviewGR.getValue( 
                        resultField 
                    ) 
                ); 


            /* ================================================= 
               STRICT SELECTED CONDITION

               COMPLETED + PASS
               ================================================= */ 

            if ( 
                interviewStatus != 'completed' && 
                interviewStatus != 'complete' 
            ) { 

                continue; 
            } 

            if ( 
                interviewResult != 'pass' 
            ) { 

                continue; 
            } 


            /* ================================================= 
               DRIVE 
               ================================================= */ 

            var driveId = 
                driveField ? 
                interviewGR.getValue( 
                    driveField 
                ) : 
                ''; 


            /* ================================================= 
               APPLICATION 
               ================================================= */ 

            var applicationGR = 
                resolveInterviewApplication( 
                    interviewGR, 
                    driveId 
                ); 

            if (!applicationGR) { 
                continue; 
            } 


            /* ================================================= 
               STUDENT 
               ================================================= */ 

            var studentId = 
                applicationGR.getValue( 
                    'student' 
                ) || ''; 

            if (!studentId) { 
                continue; 
            } 


            /* ================================================= 
               DUPLICATE STUDENT PROTECTION 
               ================================================= */ 

            if ( 
                selectedStudents[studentId] 
            ) { 

                continue; 
            } 

            selectedStudents[studentId] = true; 


            /* ================================================= 
               APPLICATION DATA 
               ================================================= */ 

            var applicationData = 
                buildApplicationObject( 
                    applicationGR 
                ); 


            /* ================================================= 
               SELECTED CANDIDATE 
               ================================================= */ 

            data.interviewer.selectedCandidates.push({ 

                studentId: 
                    studentId, 

                name: 
                    applicationData.studentName || 
                    getStudentName( 
                        studentId 
                    ), 

                registerNumber: 
                    applicationData.registerNumber, 

                branch: 
                    applicationData.branch, 

                company: 
                    applicationData.company, 

                companyInitial: 
                    applicationData.companyInitial, 

                driveName: 
                    applicationData.driveName, 

                jobRole: 
                    applicationData.jobRole, 

                status: 
                    'Selected', 

                result: 
                    'Pass', 

                interviewId: 
                    interviewGR.getUniqueValue(), 

                applicationId: 
                    applicationGR.getUniqueValue() 
            }); 
        } 


        data.interviewer.selectedCandidateCount = 
            data.interviewer.selectedCandidates.length; 
    } 


    /* ========================================================= 
       STUDENT INTERVIEWS 
       ========================================================= */ 

    function loadStudentInterviews( 
        studentId 
    ) { 

        var interviewGR = 
            new GlideRecord( 
                'x_snc_college_pl_0_interview' 
            ); 

        if (!interviewGR.isValid()) { 
            return; 
        } 

        if ( 
            interviewGR.isValidField( 
                'student' 
            ) 
        ) { 

            interviewGR.addQuery( 
                'student', 
                studentId 
            ); 

        } else if ( 
            interviewGR.isValidField( 
                'application' 
            ) 
        ) { 

            var applicationIds = []; 

            var applicationGR = 
                new GlideRecord( 
                    'x_snc_college_pl_0_application' 
                ); 

            applicationGR.addQuery( 
                'student', 
                studentId 
            ); 

            applicationGR.query(); 

            while (applicationGR.next()) { 

                applicationIds.push( 
                    applicationGR.getUniqueValue() 
                ); 
            } 

            if (applicationIds.length > 0) { 

                interviewGR.addQuery( 
                    'application', 
                    'IN', 
                    applicationIds.join(',') 
                ); 

            } else { 

                return; 
            } 
        } 

        interviewGR.orderBy( 
            'interview_date' 
        ); 

        interviewGR.query(); 

        while (interviewGR.next()) { 

            data.interviewCount++; 

            var interview = 
                buildInterviewObject( 
                    interviewGR 
                ); 

            if (!data.upcomingInterview) { 

                data.upcomingInterview = 
                    interview; 
            } 
        } 
    } 


    /* ========================================================= 
       BUILD APPLICATION OBJECT 
       ========================================================= */ 

    function buildApplicationObject( 
        applicationGR 
    ) { 

        var studentName = ''; 
        var registerNumber = ''; 
        var branch = ''; 

        var studentId = 
            applicationGR.getValue( 
                'student' 
            ); 

        if (studentId) { 

            var studentGR = 
                new GlideRecord( 
                    'x_snc_college_pl_0_student' 
                ); 

            if (studentGR.get(studentId)) { 

                studentName = 
                    studentGR.getDisplayValue( 
                        'name' 
                    ) || 
                    studentGR.getDisplayValue( 
                        'user' 
                    ) || 
                    ''; 

                if ( 
                    studentGR.isValidField( 
                        'register_number' 
                    ) 
                ) { 

                    registerNumber = 
                        studentGR.getValue( 
                            'register_number' 
                        ) || ''; 
                } 

                if ( 
                    studentGR.isValidField( 
                        'branch' 
                    ) 
                ) { 

                    branch = 
                        studentGR.getDisplayValue( 
                            'branch' 
                        ) || ''; 
                } 
            } 
        } 

        var company = 'Company'; 
        var driveName = 'Placement Drive'; 
        var jobRole = 
            'Placement Opportunity'; 

        var driveId = 
            applicationGR.getValue( 
                'drive' 
            ); 

        if (driveId) { 

            var driveGR = 
                new GlideRecord( 
                    'x_snc_college_pl_0_placement_drive' 
                ); 

            if (driveGR.get(driveId)) { 

                company = 
                    driveGR.getDisplayValue( 
                        'company' 
                    ) || 
                    'Company'; 

                driveName = 
                    getFirstValidValue( 
                        driveGR, 
                        [ 
                            'drive_name', 
                            'name' 
                        ] 
                    ) || 
                    'Placement Drive'; 

                jobRole = 
                    getFirstValidValue( 
                        driveGR, 
                        [ 
                            'job_role', 
                            'position', 
                            'role' 
                        ] 
                    ) || 
                    'Placement Opportunity'; 
            } 
        } 

        var status = 
            applicationGR.getDisplayValue( 
                'status' 
            ) || 
            'Applied'; 

        return { 

            sys_id: 
                applicationGR.getUniqueValue(), 

            studentName: 
                studentName, 

            registerNumber: 
                registerNumber, 

            branch: 
                branch, 

            company: 
                company, 

            companyInitial: 
                getInitial( 
                    company 
                ), 

            driveName: 
                driveName, 

            position: 
                jobRole, 

            jobRole: 
                jobRole, 

            status: 
                status, 

            statusClass: 
                getStatusClass( 
                    status 
                ), 

            appliedDate: 
                applicationGR.getValue( 
                    'applied_date' 
                ) || 
                applicationGR.getValue( 
                    'sys_created_on' 
                ) 
        }; 
    } 


    /* ========================================================= 
       BUILD DRIVE OBJECT 
       ========================================================= */ 

    function buildDriveObject( 
        driveGR 
    ) { 

        var company = 
            driveGR.getDisplayValue( 
                'company' 
            ) || 
            'Company'; 

        var driveName = 
            getFirstValidValue( 
                driveGR, 
                [ 
                    'drive_name', 
                    'name' 
                ] 
            ) || 
            'Placement Drive'; 

        var jobRole = 
            getFirstValidValue( 
                driveGR, 
                [ 
                    'job_role', 
                    'position', 
                    'role' 
                ] 
            ) || 
            'Placement Opportunity'; 

        var status = 
            driveGR.getDisplayValue( 
                'status' 
            ) || 
            'Open'; 

        return { 

            sys_id: 
                driveGR.getUniqueValue(), 

            company: 
                company, 

            companyInitial: 
                getInitial( 
                    company 
                ), 

            driveName: 
                driveName, 

            jobRole: 
                jobRole, 

            position: 
                jobRole, 

            driveDate: 
                getFirstValidValue( 
                    driveGR, 
                    [ 
                        'drive_date', 
                        'date' 
                    ] 
                ), 

            status: 
                status 
        }; 
    } 


    /* ========================================================= 
       BUILD GENERAL INTERVIEW OBJECT 
       ========================================================= */ 

    function buildInterviewObject( 
        interviewGR 
    ) { 

        var studentName = ''; 

        if ( 
            interviewGR.isValidField( 
                'student' 
            ) 
        ) { 

            var studentId = 
                interviewGR.getValue( 
                    'student' 
                ) || ''; 

            if (studentId) { 

                studentName = 
                    getStudentName( 
                        studentId 
                    ); 
            } 
        } 

        if ( 
            !studentName && 
            interviewGR.isValidField( 
                'application' 
            ) 
        ) { 

            var applicationId = 
                interviewGR.getValue( 
                    'application' 
                ) || ''; 

            if (applicationId) { 

                var applicationGR = 
                    new GlideRecord( 
                        'x_snc_college_pl_0_application' 
                    ); 

                if ( 
                    applicationGR.get( 
                        applicationId 
                    ) 
                ) { 

                    studentName = 
                        getStudentName( 
                            applicationGR.getValue( 
                                'student' 
                            ) 
                        ); 
                } 
            } 
        } 

        var company = 
            getFirstValidValue( 
                interviewGR, 
                [ 
                    'company' 
                ] 
            ); 

        var position = 
            getFirstValidValue( 
                interviewGR, 
                [ 
                    'position', 
                    'job_role', 
                    'role' 
                ] 
            ); 

        var driveField = 
            findValidField( 
                interviewGR, 
                [ 
                    'drive', 
                    'placement_drive' 
                ] 
            ); 

        var driveId = 
            driveField ? 
            interviewGR.getValue( 
                driveField 
            ) : 
            ''; 

        var driveName = 
            driveField ? 
            interviewGR.getDisplayValue( 
                driveField 
            ) : 
            ''; 

        if (driveId) { 

            var driveGR = 
                new GlideRecord( 
                    'x_snc_college_pl_0_placement_drive' 
                ); 

            if (driveGR.get(driveId)) { 

                if (!company) { 

                    company = 
                        driveGR.getDisplayValue( 
                            'company' 
                        ); 
                } 

                if (!position) { 

                    position = 
                        getFirstValidValue( 
                            driveGR, 
                            [ 
                                'job_role', 
                                'position', 
                                'role' 
                            ] 
                        ); 
                } 

                if (!driveName) { 

                    driveName = 
                        getFirstValidValue( 
                            driveGR, 
                            [ 
                                'drive_name', 
                                'name' 
                            ] 
                        ); 
                } 
            } 
        } 

        var status = 
            getFirstValidValue( 
                interviewGR, 
                [ 
                    'status', 
                    'state' 
                ] 
            ) || 
            'Scheduled'; 

        var result = 
            getFirstValidValue( 
                interviewGR, 
                [ 
                    'result', 
                    'interview_result' 
                ] 
            ) || ''; 

        return { 

            sys_id: 
                interviewGR.getUniqueValue(), 

            studentName: 
                studentName || 
                'Candidate', 

            company: 
                company || 
                'Company', 

            companyInitial: 
                getInitial( 
                    company || 
                    'Company' 
                ), 

            drive: 
                driveName || 
                'Placement Drive', 

            driveName: 
                driveName || 
                'Placement Drive', 

            position: 
                position || 
                'Interview', 

            jobRole: 
                position || 
                'Interview', 

            date: 
                getFirstValidValue( 
                    interviewGR, 
                    [ 
                        'interview_date', 
                        'date' 
                    ] 
                ), 

            time: 
                getFirstValidValue( 
                    interviewGR, 
                    [ 
                        'interview_time', 
                        'time' 
                    ] 
                ), 

            status: 
                status, 

            statusClass: 
                getStatusClass( 
                    status 
                ), 

            result: 
                result, 

            feedback: 
                getFirstValidValue( 
                    interviewGR, 
                    [ 
                        'feedback', 
                        'interview_feedback' 
                    ] 
                ) || '' 
        }; 
    } 


    /* ========================================================= 
       FIND VALID FIELD 
       ========================================================= */ 

    function findValidField( 
        gr, 
        fields 
    ) { 

        for ( 
            var i = 0; 
            i < fields.length; 
            i++ 
        ) { 

            if ( 
                gr.isValidField( 
                    fields[i] 
                ) 
            ) { 

                return fields[i]; 
            } 
        } 

        return ''; 
    } 


    /* ========================================================= 
       GET FIRST VALID VALUE 
       ========================================================= */ 

    function getFirstValidValue( 
        gr, 
        fields 
    ) { 

        for ( 
            var i = 0; 
            i < fields.length; 
            i++ 
        ) { 

            var field = 
                fields[i]; 

            if ( 
                gr.isValidField( 
                    field 
                ) 
            ) { 

                var value = 
                    gr.getDisplayValue( 
                        field 
                    ); 

                if (!value) { 

                    value = 
                        gr.getValue( 
                            field 
                        ); 
                } 

                if (value) { 

                    return value; 
                } 
            } 
        } 

        return ''; 
    } 


    /* ========================================================= 
       NORMALIZE STATUS 
       ========================================================= */ 

    function normalizeStatus( 
        status 
    ) { 

        return String( 
            status || '' 
        ) 
        .toLowerCase() 
        .replace( 
            /_/g, 
            ' ' 
        ) 
        .trim(); 
    } 


    /* ========================================================= 
       GET INITIAL 
       ========================================================= */ 

    function getInitial( 
        value 
    ) { 

        if (!value) { 
            return 'N'; 
        } 

        value = 
            String(value).trim(); 

        if (!value) { 
            return 'N'; 
        } 

        return value 
            .charAt(0) 
            .toUpperCase(); 
    } 


    /* ========================================================= 
       STATUS CLASS 
       ========================================================= */ 

    function getStatusClass( 
        status 
    ) { 

        var value = 
            normalizeStatus( 
                status 
            ); 

        if ( 
            value.indexOf( 
                'selected' 
            ) != -1 
        ) { 

            return 'status-selected'; 
        } 

        if ( 
            value.indexOf( 
                'short' 
            ) != -1 
        ) { 

            return 'status-shortlisted'; 
        } 

        if ( 
            value.indexOf( 
                'reject' 
            ) != -1 
        ) { 

            return 'status-rejected'; 
        } 

        if ( 
            value.indexOf( 
                'interview' 
            ) != -1 
        ) { 

            return 'status-interview'; 
        } 

        if ( 
            value.indexOf( 
                'offer' 
            ) != -1 
        ) { 

            return 'status-offered'; 
        } 

        if ( 
            value.indexOf( 
                'completed' 
            ) != -1 
        ) { 

            return 'status-completed'; 
        } 

        return 'status-applied'; 
    } 


    /* ========================================================= 
       STUDENT PERCENTAGES 
       ========================================================= */ 

    function calculateStudentPercentages() { 

        var total = 
            data.applicationStatusChart.total; 

        if (total <= 0) { 
            return; 
        } 

        data.applicationStatusChart.appliedPercent = 
            Math.round( 
                ( 
                    data.applicationStatusChart.applied / 
                    total 
                ) * 100 
            ); 

        data.applicationStatusChart.shortlistedPercent = 
            Math.round( 
                ( 
                    data.applicationStatusChart.shortlisted / 
                    total 
                ) * 100 
            ); 

        data.applicationStatusChart.interviewPercent = 
            Math.round( 
                ( 
                    data.applicationStatusChart.interview / 
                    total 
                ) * 100 
            ); 

        data.applicationStatusChart.selectedPercent = 
            Math.round( 
                ( 
                    data.applicationStatusChart.selected / 
                    total 
                ) * 100 
            ); 

        data.applicationStatusChart.rejectedPercent = 
            Math.round( 
                ( 
                    data.applicationStatusChart.rejected / 
                    total 
                ) * 100 
            ); 

        data.applicationStatusChart.offeredPercent = 
            Math.round( 
                ( 
                    data.applicationStatusChart.offered / 
                    total 
                ) * 100 
            ); 
    } 


})();
